CREATE TABLE players(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(64), balance DECIMAL(12,2) DEFAULT 1000.00, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE rounds(id BIGINT AUTO_INCREMENT PRIMARY KEY, player_id INT, bet DECIMAL(12,2), player_hand VARCHAR(64), dealer_hand VARCHAR(64), result ENUM('win','lose','draw'), payout DECIMAL(12,2), played_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(player_id) REFERENCES players(id));
